FROM (
    SELECT t2.job_type AS job_type, t2.id AS id, t2.status AS status, t2.created_at AS created_at
    FROM (
        SELECT DISTINCT ON (t1.job_type COLLATE "C") t1.id, t1.job_type, t1.status, t1.created_at, t1.finished_at
        FROM jobs AS t1
        ORDER BY t1.job_type COLLATE "C", t1.created_at DESC, t1.id DESC
    ) AS t2
) AS t3
ORDER BY t3.job_type COLLATE "C"
LIMIT 101;
